export function resolveOviResponse(rawInput: string) {
  const cleaned = rawInput.trim();
  const exactKey = Object.keys(OVI_KNOWLEDGE).find(
    (key) => key.toLowerCase() === cleaned.toLowerCase()
  );
  if (exactKey) return OVI_KNOWLEDGE[exactKey];

  const lower = cleaned.toLowerCase();
  const matchedAlias = KEYWORD_ALIASES.find(({ keywords }) =>
    keywords.some((kw) => lower.includes(kw))
  );
  if (matchedAlias && OVI_KNOWLEDGE[matchedAlias.targetKey]) {
    return OVI_KNOWLEDGE[matchedAlias.targetKey];
  }

  return {
    text: "Love, I want to understand you properly. Can you tell me a little more, or pick a topic below so I can hold space for you?",
    chips: ["My period is late", "I had sex, am I pregnant?", "How can I feel better right now?"],
  };
}